import{_ as a,o as e,c as s,a2 as d}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"전문 검색","description":"","frontmatter":{},"headers":[],"relativePath":"ko/advanced/search.md","filePath":"ko/advanced/search.md","lastUpdated":1784903584000}'),n={name:"ko/advanced/search.md"};function o(p,t,l,c,i,r){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="전문-검색" tabindex="-1">전문 검색 <a class="header-anchor" href="#전문-검색" aria-label="Permalink to &quot;전문 검색&quot;">​</a></h1><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>swag2mcp에는 모든 spec의 모든 엔드포인트를 인덱싱하는 내장 전문 검색 엔진(bluge)이 포함되어 있습니다. LLM은 엔드포인트 ID를 몰라도 메서드, 경로, 요약 또는 태그로 엔드포인트를 검색할 수 있습니다.</p><h2 id="인덱싱-작동-방식" tabindex="-1">인덱싱 작동 방식 <a class="header-anchor" href="#인덱싱-작동-방식" aria-label="Permalink to &quot;인덱싱 작동 방식&quot;">​</a></h2><p>spec이 추가되거나 업데이트되면 모든 엔드포인트가 인덱싱됩니다. 다음 필드를 검색할 수 있습니다:</p><table tabindex="0"><thead><tr><th>필드</th><th>설명</th><th>예시</th></tr></thead><tbody><tr><td><code>method</code></td><td>HTTP 메서드</td><td><code>GET</code>, <code>POST</code>, <code>PUT</code></td></tr><tr><td><code>path</code></td><td>API 엔드포인트 경로</td><td><code>/api/v1/users/{id}</code></td></tr><tr><td><code>summary</code></td><td>OpenAPI 요약</td><td>&quot;Find pet by ID&quot;</td></tr><tr><td><code>tag</code></td><td>엔드포인트 카테고리</td><td>&quot;pets&quot;, &quot;users&quot;</td></tr><tr><td><code>_all</code></td><td>모든 필드 결합</td><td>method + path + tag + summary</td></tr></tbody></table><p>인덱스는 MCP 서버가 시작될 때마다 재구축됩니다. 빠른 검색을 위해 메모리에 저장됩니다.</p><h2 id="쿼리-구문" tabindex="-1">쿼리 구문 <a class="header-anchor" href="#쿼리-구문" aria-label="Permalink to &quot;쿼리 구문&quot;">​</a></h2><p>검색은 정밀한 필터링을 위한 풍부한 쿼리 구문을 지원합니다:</p><table tabindex="0"><thead><tr><th>예시</th><th>설명</th></tr></thead><tbody><tr><td><code>pet</code></td><td>모든 필드에 대한 단순 텍스트 검색</td></tr><tr><td><code>method:GET</code></td><td>모든 GET 엔드포인트 찾기</td></tr><tr><td><code>tag:pets</code></td><td>&quot;pets&quot; 태그의 엔드포인트 찾기</td></tr><tr><td><code>path:&quot;/api/v1/users&quot;</code></td><td>정확한 경로 일치</td></tr><tr><td><code>+method:POST +tag:pet</code></td><td>두 조건 모두 일치해야 함</td></tr><tr><td><code>-method:DELETE</code></td><td>DELETE 메서드 제외</td></tr><tr><td><code>create~</code></td><td>퍼지 검색 (오타 허용)</td></tr><tr><td><code>cr*</code></td><td>와일드카드 검색</td></tr><tr><td><code>&quot;find pet&quot;</code></td><td>구문 검색</td></tr><tr><td><code>+summary:pet -method:DELETE</code></td><td>요약에 &quot;pet&quot; 포함, DELETE 제외</td></tr></tbody></table><h3 id="필드별-검색" tabindex="-1">필드별 검색 <a class="header-anchor" href="#필드별-검색" aria-label="Permalink to &quot;필드별 검색&quot;">​</a></h3><p><code>field:value</code> 구문을 사용하여 특정 필드 내에서 검색할 수 있습니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>method:GET</span></span>
<span class="line"><span>tag:pets</span></span>
<span class="line"><span>path:&quot;/pet/findByStatus&quot;</span></span>
<span class="line"><span>summary:&quot;find pet by status&quot;</span></span></code></pre></div><h3 id="부울-연산자" tabindex="-1">부울 연산자 <a class="header-anchor" href="#부울-연산자" aria-label="Permalink to &quot;부울 연산자&quot;">​</a></h3><ul><li><code>+</code> — 용어가 반드시 일치해야 함 (AND)</li><li><code>-</code> — 용어가 일치하지 않아야 함 (NOT)</li><li>용어 사이의 공백 — OR (모든 용어가 일치 가능)</li></ul><h3 id="퍼지-및-와일드카드" tabindex="-1">퍼지 및 와일드카드 <a class="header-anchor" href="#퍼지-및-와일드카드" aria-label="Permalink to &quot;퍼지 및 와일드카드&quot;">​</a></h3><ul><li><code>term~</code> — 퍼지 검색 (유사한 단어 일치, 오타 처리)</li><li><code>te*</code> — 와일드카드 (모든 문자 일치)</li><li><code>te?t</code> — 단일 문자 와일드카드</li></ul><h2 id="예시" tabindex="-1">예시 <a class="header-anchor" href="#예시" aria-label="Permalink to &quot;예시&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 모든 GET 요청 찾기</span></span>
<span class="line"><span>method:GET</span></span>
<span class="line"><span></span></span>
<span class="line"><span># pet 태그의 POST 요청 찾기</span></span>
<span class="line"><span>+method:POST +tag:pet</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 정확한 경로로 엔드포인트 찾기</span></span>
<span class="line"><span>path:&quot;/pet/findByStatus&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 설명으로 찾기</span></span>
<span class="line"><span>&quot;find pet by status&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># DELETE를 제외한 모든 항목 찾기</span></span>
<span class="line"><span>+summary:pet -method:DELETE</span></span>
<span class="line"><span></span></span>
<span class="line"><span># &quot;create&quot; 퍼지 검색 (오타 처리)</span></span>
<span class="line"><span>create~</span></span></code></pre></div><h2 id="mcp-도구" tabindex="-1">MCP 도구 <a class="header-anchor" href="#mcp-도구" aria-label="Permalink to &quot;MCP 도구&quot;">​</a></h2><p><code>search</code> MCP 도구는 LLM에 검색 엔진을 노출합니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>→ search(query: &quot;find pet by status&quot;, limit: 5)</span></span>
<span class="line"><span>← GET /pet/findByStatus — 상태별 애완동물 찾기</span></span>
<span class="line"><span>   GET /pet/{petId} — ID로 애완동물 찾기</span></span></code></pre></div><h3 id="매개변수" tabindex="-1">매개변수 <a class="header-anchor" href="#매개변수" aria-label="Permalink to &quot;매개변수&quot;">​</a></h3><table tabindex="0"><thead><tr><th>매개변수</th><th>필수</th><th>설명</th></tr></thead><tbody><tr><td><code>query</code></td><td>예</td><td>검색 쿼리 (구조화된 구문 지원)</td></tr><tr><td><code>limit</code></td><td>예</td><td>최대 결과 수 (1-50)</td></tr></tbody></table><h2 id="중요-참고-사항" tabindex="-1">중요 참고 사항 <a class="header-anchor" href="#중요-참고-사항" aria-label="Permalink to &quot;중요 참고 사항&quot;">​</a></h2><ul><li><strong>인덱스는 메모리 내</strong> — MCP 서버가 시작될 때마다 재구축됩니다. 영구 인덱스 파일이 없습니다.</li><li><strong>모든 필드는 소문자로 변환됨</strong> — 검색은 대소문자를 구분하지 않습니다</li><li><strong>제한은 최대 50개</strong> — 50개 이상의 결과를 요청할 수 없습니다</li><li><strong>잘못된 쿼리 구문</strong>은 예제와 함께 도움이 되는 오류 메시지를 반환합니다</li><li><strong><code>_all</code> 필드</strong>는 method, path, tag, summary를 결합하여 단순 텍스트 검색에 사용됩니다</li></ul>`,26)])])}const b=a(n,[["render",o]]);export{u as __pageData,b as default};
